struct context {
    const struct scenario *scenario;
    vireo_result_t name_rc;
    vireo_directory_name_issue_t issue;
    size_t names, repos;
    vireo_mysql_node_repository_t *repo;
    const vireo_mysql_node_actor_t *actor;
    const vireo_mysql_node_move_once_input_t *input;
    uint32_t timeout;
};
static vireo_result_t name_callback(void *ctx, const unsigned char *name, size_t length,
    vireo_directory_name_issue_t *issue)
{
    struct context *c=ctx; ++c->names;
    assert(name==c->input->name && length==c->input->name_length);
    *issue=c->issue; errno=ERANGE; return c->name_rc;
}
static vireo_result_t repo_callback(void *ctx, vireo_mysql_node_repository_t *repo,
    const vireo_mysql_node_actor_t *actor, const vireo_mysql_node_move_once_input_t *input,
    uint32_t timeout, vireo_mysql_node_move_once_report_t *report, vireo_mysql_node_error_t *error)
{
    struct context *c=ctx; ++c->repos;
    assert(c->repos==1 && repo==c->repo && actor==c->actor && input==c->input && timeout==c->timeout);
    assert(error!=NULL); *report=c->scenario->report;
    error->cleanup_result=c->scenario->cleanup;
    error->database.mysql_code=1062; /* 技术重复键错误不可提升为占名。 */
    error->system_errno=EIO; errno=EBUSY; return c->scenario->rc;
}
static bool zero(const void *p, size_t n)
{
    const unsigned char *b=p;
    for(size_t i=0;i<n;++i) { if(b[i]!=0) { return false; } } return true;
}
static void report_equal(const vireo_mysql_node_move_once_report_t *a,
    const vireo_mysql_node_move_once_report_t *b)
{
    assert(a->commit==b->commit && a->effect==b->effect && a->issue==b->issue);
    assert(a->node_id==b->node_id && a->audit_id==b->audit_id);
    assert(a->rollback_confirmed==b->rollback_confirmed && a->cleanup_pending==b->cleanup_pending);
    assert(memcmp(a->idempotency_key,b->idempotency_key,16)==0);
}
int main(void)
{
    unsigned char opaque=0;
    vireo_mysql_node_repository_t *repo=(vireo_mysql_node_repository_t *)(void *)&opaque;
    vireo_mysql_node_actor_t actor={1,2};
    vireo_mysql_node_move_once_input_t input={.node_id=31,.new_parent_id=44,
        .name=(const unsigned char *)"bb",.name_length=2,.idempotency_key={[15]=0x71},.request_id={0x82}};
    const vireo_mysql_node_move_once_input_t original=input;
    vireo_directory_move_result_t out; vireo_mysql_node_error_t error;
    struct context c={.scenario=&scenarios[0],.repo=repo,.actor=&actor,.input=&input,.timeout=60000};
    vireo_directory_move_runtime_t rt={&c,name_callback,repo_callback};
    size_t count=0;
    for(size_t i=0;i<sizeof(scenarios)/sizeof(scenarios[0]);++i) {
        for(unsigned diagnostics=0;diagnostics<2;++diagnostics) {
            const struct scenario *s=&scenarios[i]; c.scenario=s;c.names=0;c.repos=0;
            memset(&out,0xa5,sizeof(out));memset(&error,0xa5,sizeof(error));errno=EDOM;
            vireo_result_t got=vireo_directory_service_move_with_runtime(repo,&actor,&input,c.timeout,
                &out,diagnostics ? &error : NULL,&rt);
            if(got!=s->want || out.outcome!=s->outcome) {
                fprintf(stderr,"%s rc/outcome %d/%d expected %d/%d\n",s->label,(int)got,(int)out.outcome,
                    (int)s->want,(int)s->outcome);abort();
            }
            assert(errno==EDOM && c.names==1 && c.repos==1 && out.repository_called);
            assert(out.repository_result==s->rc);report_equal(&out.repository,&s->report);
            assert(out.name_issue==VIREO_DIRECTORY_NAME_ISSUE_NONE);
            bool deliver=s->outcome==VIREO_DIRECTORY_MOVE_APPLIED || s->outcome==VIREO_DIRECTORY_MOVE_RECOVERED;
            assert(out.node_id==(deliver ? 31U : 0U));
            assert(deliver ? memcmp(out.idempotency_key,input.idempotency_key,16)==0 : zero(out.idempotency_key,16));
            if(diagnostics) { assert(error.cleanup_result==s->cleanup && error.system_errno==EIO && error.database.mysql_code==1062); }
            assert(memcmp(&input,&original,sizeof(input))==0 && actor.user_id==1 && actor.session_id==2);++count;
        }
    }
    c.scenario=&scenarios[0];
    /* 独立名字规范表：13个rc乘5个issue，包括不允许的技术配对。 */
    for(unsigned rc=0;rc<13;++rc) {
        for(unsigned issue=0;issue<5;++issue) {
            c.names=0;c.repos=0;c.name_rc=(vireo_result_t)rc;c.issue=(vireo_directory_name_issue_t)issue;
            const bool pass=rc==0 && issue==0;
            const bool invalid=(rc==2 && issue==1) || (rc==10 && issue>=2);
            const bool technical=(rc==3 || rc==4 || rc==12) && issue==0;
            vireo_result_t want=pass ? VIREO_OK : invalid || technical ? (vireo_result_t)rc : VIREO_RESULT_INTERNAL;
            vireo_directory_move_outcome_t outcome=pass ? VIREO_DIRECTORY_MOVE_APPLIED : invalid ? VIREO_DIRECTORY_MOVE_INVALID_NAME : VIREO_DIRECTORY_MOVE_NONE;
            errno=EDOM;
            assert(vireo_directory_service_move_with_runtime(repo,&actor,&input,c.timeout,&out,&error,&rt)==want);
            assert(errno==EDOM && c.names==1 && c.repos==(pass ? 1U : 0U));
            assert(out.outcome==outcome && out.repository_called==pass);
            assert(out.name_issue==(invalid ? c.issue : VIREO_DIRECTORY_NAME_ISSUE_NONE));
            if(!pass) { assert(zero(&out.repository,sizeof(out.repository)) && zero(&error,sizeof(error)) && out.node_id==0 && zero(out.idempotency_key,16)); }
            ++count;
        }
    }
    c.name_rc=VIREO_OK;c.issue=VIREO_DIRECTORY_NAME_ISSUE_NONE;c.timeout=0;
    for(unsigned bad=0;bad<8;++bad) {
        c.names=0;c.repos=0;memset(&out,0xa5,sizeof(out));memset(&error,0xa5,sizeof(error));
        unsigned char saved[sizeof(out)],saved_error[sizeof(error)];memcpy(saved,&out,sizeof(out));memcpy(saved_error,&error,sizeof(error));
        vireo_directory_move_runtime_t broken=rt;
        if(bad==5) { broken.name_validate=NULL; }if(bad==6) { broken.move_once=NULL; }if(bad==7) { input.name=NULL; }
        errno=EDOM;
        assert(vireo_directory_service_move_with_runtime(bad==0 ? NULL : repo,bad==1 ? NULL : &actor,
            bad==2 ? NULL : &input,0,bad==3 ? NULL : &out,&error,bad==4 ? NULL : &broken)==VIREO_RESULT_INVALID_ARGUMENT);
        assert(errno==EDOM && !c.names && !c.repos && memcmp(&out,saved,sizeof(out))==0 && memcmp(&error,saved_error,sizeof(error))==0);
        input=original;++count;
    }
    for(unsigned bad=0;bad<7;++bad) {
        c.names=0;c.repos=0;input=original;actor=(vireo_mysql_node_actor_t){1,2};
        if(bad==0) { actor.user_id=0; }if(bad==1) { actor.session_id=0; }
        if(bad==2) { input.node_id=0; }if(bad==3) { input.new_parent_id=0; }
        if(bad==4) { memset(input.idempotency_key,0,16); }if(bad==5) { memset(input.request_id,0,16); }
        errno=EDOM;
        assert(vireo_directory_service_move_with_runtime(repo,&actor,&input,bad==6 ? 60001 : 0,&out,&error,&rt)==
            (bad==6 ? VIREO_RESULT_RANGE : VIREO_RESULT_INVALID_ARGUMENT));
        assert(errno==EDOM && !c.names && !c.repos && zero(&out,sizeof(out)) && zero(&error,sizeof(error)));++count;
    }
    /* 原生名字长度拒绝必须先于读取：不可读页不是有效名字缓冲区。 */
    long page_size=sysconf(_SC_PAGESIZE);assert(page_size>0);
    void *guard=mmap(NULL,(size_t)page_size,PROT_NONE,MAP_PRIVATE|MAP_ANONYMOUS,-1,0);assert(guard!=MAP_FAILED);
    const size_t lengths[]={0,256,SIZE_MAX};input=original;actor=(vireo_mysql_node_actor_t){1,2};input.name=guard;
    for(size_t i=0;i<sizeof(lengths)/sizeof(lengths[0]);++i) {
        input.name_length=lengths[i];errno=EDOM;
        assert(vireo_directory_service_move(repo,&actor,&input,0,&out,&error)==VIREO_RESULT_RANGE);
        assert(errno==EDOM && out.outcome==VIREO_DIRECTORY_MOVE_INVALID_NAME && out.name_issue==VIREO_DIRECTORY_NAME_ISSUE_LENGTH && !out.repository_called);++count;
    }
    assert(munmap(guard,(size_t)page_size)==0);
    printf("PASS %zu service model observations; %zu report scenarios x optional diagnostics, 65 name relations, pointer/value gates, inaccessible-name length guard\n",count,sizeof(scenarios)/sizeof(scenarios[0]));
    return 0;
}
